  | Defect_asyncFiber
  | Defect_badName
  | Defect_missingService
  | Defect_user of int
  | Defect_error of err
and ('nu, 's, 'b, 'e, 'd, 'i, 'a, 'k) prim_interp = {
  cont_a : 'nu -> 'b -> 'k;
  cont_e : 'nu -> ('e, 'd, 'i, 'a) cause -> 'k;
  sync_value : 's -> 'b;
  suspend_body : 's -> 'k;
  finalizer_exit : 'nu -> ('b, 'e, 'd, 'i, 'a) exit_ -> (unit, 'e, 'd, 'i, 'a) exit_;
  reify_exit : ('b, 'e, 'd, 'i, 'a) exit_ -> 'b;
  iter_next : 'nu -> 'b -> 'b list * ('nu, 's, 'b, 'e, 'd, 'i, 'a, 'k) iter_step;
  loop_test : 'nu -> 'b -> bool;
  loop_body : 'nu -> 'b -> 'k;
  loop_step : 'nu -> 'b -> 'b -> 'b;
  loop_done : 'nu -> 'b;
  not_implemented : 'd;
  cancel_then_fail : 'nu -> ('e, 'd, 'i, 'a) cause -> 'k;
}
and eff_name =
