  race_settle : int -> bool -> ('b, 'e, 'd, 'i, 'a) exit_ -> 'k;
  finalizer_program : 'nu -> ('b, 'e, 'd, 'i, 'a) exit_ -> 'k option;
  restore_name : ('b, 'e, 'd, 'i, 'a) exit_ -> 'nu;
  merge_name : ('b, 'e, 'd, 'i, 'a) exit_ -> 'nu;
  scope_status : int -> 'st -> ('b, 'e, 'd, 'i, 'a) exit_ option option;
